function horizonTable(set,slip){const L=leaves(set);if(!L.length)return "";const rows=HZA().map((h,i)=>{const sw=L.reduce((a,x)=>a+x.w,0)||1,t=L.reduce((a,n)=>a+sc5(n,tgtN(n,i))*n.w,0)/sw,f=L.reduce((a,n)=>a+sc5(n,fore(n,HW[i],slip))*n.w,0)/sw,met=L.filter(n=>fore(n,HW[i],slip)>=tgtN(n,i)-.001).length,st=met/L.length>=.8?"good":met/L.length>=.5?"warn":"bad";return `<tr><th scope="row">${h[0]} <small class="muted">${h[2]}</small></th><td class="num" data-role="metric">${fv(t)}</td><td class="num" data-role="metric">${fv(f)}</td><td class="num" data-role="metric">${met} of ${L.length}</td><td>${stPill(st)}</td></tr>`}).join("");
 return `<div class="tscroll"><table class="mat-heat"><thead><tr><th>Horizon</th><th>Target level</th><th>Forecast level</th><th>Meeting target</th><th>Status</th></tr></thead><tbody>${rows}</tbody></table></div><div class="formula" data-role="metric">Glide variance = current level − expected level today = ${fv(roll(L,slip).cur)} − ${fv(roll(L,slip).exp)} = ${r2(roll(L,slip).cur-roll(L,slip).exp)} levels (scaled to 5). Levels are scaled to a common 1 to 5 range so a 4-tier model compares fairly with a 5-level one.</div>`}
