function crRows(slip){const out=[];leaves().forEach(n=>n.cr.forEach(c=>{const p=projInfo(c.p),t=/^PR/.test(c.p)?TASK(c.ms):null,fin=finishWd(c)+slipWd(c,slip),cd=crDate(c,slip),acc=accepted(n,c),del=t&&t.pct>=100,t1=tgtN(n,0);
 const state=acc?"Counted":del&&p.funded?"Awaiting acceptance":p.funded?"Planned":"Not funded";
 out.push({key:ckey(n,c),n,c,p,ms:t?t.n:(/^D/.test(c.p)?"Request delivered":"Project closes"),fin,cd,acc,state,slack:c.to>=t1&&!acc&&p.funded?HW[0]-cd:null,id:ckey(n,c)})}));return out}
const stateCls=s=>s==="Counted"?"good":s==="Awaiting acceptance"?"warn":s==="Planned"?"info":"mute";
function slipSim(){const sl={[M.slip.proj]:M.slip.wk},L=leaves(),flips=[];L.forEach(n=>{const t=tgtN(n,0);if(!n.cr.some(c=>c.p===M.slip.proj))return;const b=fore(n,HW[0]),a=fore(n,HW[0],sl),sb=slack(n,0),sa=slack(n,0,sl);if(b>=t-.001&&a<t-.001)flips.push({n,b,a,t,kind:"miss",sb,sa});else if(sa.s!=null&&sa.s<15&&sb.s!=null&&sb.s>=15&&b>=t-.001)flips.push({n,b,a,t,kind:"tight",sb,sa})});return flips}
function projSlack(){const m={};crRows().forEach(r=>{if(r.slack==null)return;const k=r.c.p;m[k]=Math.min(m[k]==null?1e9:m[k],r.slack)});return Object.keys(m).map(k=>({id:k,p:projInfo(k),s:m[k]})).sort((a,b)=>a.s-b.s)}
