 const axes=w.rows.filter(r=>!r.n.root&&(r.n.parent===n.id||r.n.parent==null||w.rows.length<=10||!r.leaf)).slice(0,10);const ax=(axes.length>=3?axes:w.rows.filter(r=>!r.n.root).slice(0,8));
 const rad=radarSVG(ax.map(r=>r.n.name),[{l:"Level today",c:"--accent",v:ax.map(r=>r.cur),fill:1},{l:"Funded forecast",c:"--warn-f",v:ax.map(r=>r.leaf?Math.min(r.cv,r.req):r.cur),dash:1},{l:"Required",c:"--bad-f",v:ax.map(r=>r.req),dash:1}],5);
