 const ord=p.caps.slice().sort((a,b)=>(a.parent?1:0)-(b.parent?1:0));ord.forEach(c=>{n++;const id=c.parent&&idOf[c.parent]?idOf[c.parent]+String.fromCharCode(96+n%26+1):P+"."+n,i=p.caps.indexOf(c),mp=map[i]||aiMap(c);idOf[c.name]=id;
  const y1=c.y1!=null?c.y1:Math.min(max,c.cur+1),y3=c.y3!=null?c.y3:Math.min(max,y1+(max>3?1:0)),y5=c.y5!=null?c.y5:Math.min(max,y3+1);
  const o={id,model:mo.id,parent:c.parent&&idOf[c.parent]?idOf[c.parent]:P,name:c.name,cur:c.cur,t:[y1,Math.max(y1,y3),Math.max(y1,y3,y5)],conf:.6,owner:c.owner||mo.own,objs:(mp.objs||[]).slice(),svcs:(mp.svcs||[]).slice(),pre:[],cr:[],mt:[],sk:[],w:1,b0:c.cur,eff:1.5+(n%3)*.5,mo:3+(n%3),root:0,note:c.desc||""};XCAPS().push(o);reg(o)});
