 if(!I.txt.trim())return `<div class="emptystate"><b>Nothing to read yet</b><span class="muted">Paste a model, choose a file, or load a sample. The parser shows what it understood before anything is saved.</span></div>`;
 p.caps.forEach((c,i)=>{if(!I.map[i]||I.map[i].auto)I.map[i]=aiMap(c)});Object.keys(I.map).forEach(k=>{if(+k>=p.caps.length)delete I.map[k]});
