 const board=`<div class="mat-mapb">${cols.map(c=>{const items=p.caps.map((x,i)=>({x,i,m:I.map[i]||{}})).filter(z=>c.id==="none"?!(z.m.objs||[]).length:(z.m.objs||[])[0]===c.id);return `<div class="mat-mapc glass" data-dnd="${c.id}" data-dnd-scope="matmap"><div class="mat-maph"><b>${H(c.t)}</b><span class="pill mute">${items.length}</span></div>${items.slice(0,40).map(z=>`<div class="mat-mapi" data-dnd-id="${z.i}" tabindex="0">${grip}<span><b>${H(z.x.name)}</b><small class="muted">${z.m.auto?Math.round((z.m.conf||0)*100)+"% · "+H((z.m.svcs||[]).map(s=>(svcOf(s)||{n:s}).n).join(", ")||"no service"):"moved by you"}</small></span></div>`).join("")}${items.length>40?`<span class="muted small">+${items.length-40} more</span>`:""}</div>`}).join("")}</div>`;
 const tree=p.caps.filter(c=>!c.parent).map(c=>`<tr><th scope="row">${H(c.name)}</th><td class="num">${c.cur}</td><td class="num">${c.y1==null?"auto":c.y1}</td><td class="num">${c.y3==null?"auto":c.y3}</td><td class="num">${c.y5==null?"auto":c.y5}</td><td>${H(c.owner||"model owner")}</td></tr>`+p.caps.filter(k=>k.parent===c.name).map(k=>`<tr class="sub"><th scope="row">› ${H(k.name)}</th><td class="num">${k.cur}</td><td class="num">${k.y1==null?"auto":k.y1}</td><td class="num">${k.y3==null?"auto":k.y3}</td><td class="num">${k.y5==null?"auto":k.y5}</td><td>${H(k.owner||"model owner")}</td></tr>`).join("")).join("");
